                    (state % (2 * limit + 1)) as i32 - limit as i32
                };
                values.push(value);
            }
            for prefix in 0..8 {
                compare(cb, &values, prefix);
                compare(cb, &vec![0; len], prefix);
                compare(cb, &vec![(limit + 1) as i32; len], prefix);
            }
        }
    }
}

